import java.util.LinkedHashMap;
import java.util.Map;

public class Ex07L2CacheNamespace {

    static class Database {
        int queries = 0;

        String query(String sql) {
            queries++;
            return "row-of:" + sql;
        }
    }

    static class Configuration {
        final Database db;
        final Map<String, Map<String, String>> l2 = new LinkedHashMap<String, Map<String, String>>();

        Configuration(Database db) {
            this.db = db;
        }

        Map<String, String> namespaceCache(String ns) {
            Map<String, String> c = l2.get(ns);
            if (c == null) {
                c = new LinkedHashMap<String, String>();
                l2.put(ns, c);
            }
            return c;
        }

        void flushNamespace(String ns) {
            namespaceCache(ns).clear();
        }
    }

    static class SqlSession {
        final Configuration cfg;
        final String namespace;
        final Map<String, String> l1 = new LinkedHashMap<String, String>();
        int l1Hits = 0;
        int l2Hits = 0;

        SqlSession(Configuration cfg, String namespace) {
            this.cfg = cfg;
            this.namespace = namespace;
        }

        String select(String sql) {
            if (l1.containsKey(sql)) {
                l1Hits++;
                return l1.get(sql);
            }
            Map<String, String> ns = cfg.namespaceCache(namespace);
            if (ns.containsKey(sql)) {
                l2Hits++;
                l1.put(sql, ns.get(sql));
                return ns.get(sql);
            }
            String v = cfg.db.query(sql);
            l1.put(sql, v);
            return v;
        }

        // 增删改清空本 namespace 的二级缓存 + 本会话一级缓存
        void update(String sql) {
            cfg.db.queries++;
            cfg.flushNamespace(namespace);
            l1.clear();
        }

        // 提交时才把一级缓存晋升到 namespace 级二级缓存
        void commit() {
            cfg.namespaceCache(namespace).putAll(l1);
        }
    }

    public static void main(String[] args) {
        Database db = new Database();
        Configuration cfg = new Configuration(db);
        String sqlA = "SELECT id FROM t_user WHERE id = 1";

        SqlSession s1 = new SqlSession(cfg, "UserMapper");
        s1.select(sqlA);
        s1.commit();
        System.out.println("s1 UserMapper    : db=" + db.queries + " l1=" + s1.l1Hits
                + " l2=" + s1.l2Hits + " l2size=" + cfg.namespaceCache("UserMapper").size());

        SqlSession s2 = new SqlSession(cfg, "UserMapper");
        s2.select(sqlA);
        System.out.println("s2 UserMapper    : db=" + db.queries + " l1=" + s2.l1Hits
                + " l2=" + s2.l2Hits + " (cross-session L2 hit)");

        SqlSession s3 = new SqlSession(cfg, "OrderMapper");
        s3.select(sqlA);
        s3.commit();
        System.out.println("s3 OrderMapper   : db=" + db.queries + " l1=" + s3.l1Hits
                + " l2=" + s3.l2Hits + " (namespace isolated)");

        SqlSession s4 = new SqlSession(cfg, "UserMapper");
        s4.update("UPDATE t_user SET name = 'z' WHERE id = 1");
        System.out.println("s4 UserMapper upd: l2size(UserMapper)="
                + cfg.namespaceCache("UserMapper").size() + " l2size(OrderMapper)="
                + cfg.namespaceCache("OrderMapper").size());

        SqlSession s5 = new SqlSession(cfg, "UserMapper");
        s5.select(sqlA);
        System.out.println("s5 UserMapper    : db=" + db.queries + " l2=" + s5.l2Hits
                + " (L2 flushed by update)");

        SqlSession s6 = new SqlSession(cfg, "OrderMapper");
        s6.select(sqlA);
        System.out.println("s6 OrderMapper   : db=" + db.queries + " l2=" + s6.l2Hits
                + " (unaffected)");
        System.out.println("namespace isolate: " + (s6.l2Hits == 1 && s2.l2Hits == 1));
    }
}
